#!/usr/bin/env node
// Writes the playbook's generated pages (D-042, D-044) from the component contracts and the
// token build. Usage: node tools/build-playbook.mjs   Then: bundle exec jekyll build
//   playbook/components/index.md and one page per contract, with every example rendered
//   playbook/tokens.md, from tokens/build/tokens.json
//   playbook/formats/, one page per print and social format (D-043), with placeholder content
// Generated files; do not edit them by hand.

import { readFileSync, writeFileSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { parse } from 'yaml';
import { ROLE_PAIRS, contrastRatio } from './lib/tokens.mjs';

const HEADER = 'Generated by tools/build-playbook.mjs. Do not edit: change the contract or the tokens, then rebuild.';
const contracts = readdirSync('_data/components').filter((f) => f.endsWith('.yml')).sort()
  .map((f) => ({ slug: f.replace(/\.yml$/, ''), ...parse(readFileSync(`_data/components/${f}`, 'utf8')) }));

const page = (front, body) => `---\n${Object.entries(front).map(([k, v]) => `${k}: ${JSON.stringify(v)}`).join('\n')}\n---\n<!-- ${HEADER} -->\n\n${body.trim()}\n`;
const cell = (v) => (v === undefined || v === null || v === '' ? '' : String(v).replace(/\|/g, '\\|'));
const liquidValue = (v) => `"${String(v).replace(/"/g, '&quot;')}"`;
export const includeTag = (c, params) => `{% include ${c.include}${Object.entries(params || {}).map(([k, v]) => ` ${k}=${liquidValue(v)}`).join('')} %}`;

// ---- components ------------------------------------------------------------------------------
rmSync('playbook/components', { recursive: true, force: true });
mkdirSync('playbook/components', { recursive: true });
for (const c of contracts) {
  const meta = [
    `Include \`${c.include}\``,
    c.figma ? `Figma: ${c.figma}` : null,
    `Formats: ${(c.formats || []).join(', ')}`,
    c.decisions && c.decisions.length ? `Decisions: ${c.decisions.join(', ')}` : null,
    c.rules && c.rules.length ? `Rules: ${c.rules.join(', ')}` : null,
    c.data && c.data.length ? `Reads site data: ${c.data.map((d) => `\`${d}\``).join(', ')}` : null,
  ].filter(Boolean).join(' · ');
  const params = (c.params || []).length
    ? ['| Parameter | Type | Required | Default | Source | Notes |', '|---|---|---|---|---|---|',
      ...c.params.map((p) => `| \`${p.name}\` | ${p.type}${p.values ? `: ${p.values.join(', ')}` : ''} | ${p.required ? 'yes' : 'no'} | ${cell(p.default)} | ${p.source} | ${cell(p.notes)} |`)].join('\n')
    : 'None.';
  const examples = (c.examples || []).map((ex) => {
    const tag = includeTag(c, ex.params);
    const surface = ex.surface && ex.surface !== 'default' ? ` pb-example__stage--${ex.surface}` : '';
    return `### ${ex.title}\n\n<div class="pb-example"><div class="pb-example__stage${surface}">\n${tag}\n</div></div>\n\n\`\`\`liquid\n{% raw %}${tag}{% endraw %}\n\`\`\``;
  }).join('\n\n') || 'No examples: this include goes in the page head.';
  writeFileSync(`playbook/components/${c.slug}.md`, page({ title: c.name }, `
# ${c.name}

${c.summary}

${meta}

The contract is \`_data/components/${c.slug}.yml\` (COMP-002). Sources are explained in [Components](../../brand/system/components.md).

## Parameters

${params}

## Examples

${examples}
`));
}
writeFileSync('playbook/components/index.md', page({ title: 'Components' }, `
# Components

Every include in the theme, rendered from its contract (D-042). Build pages, flyers, postcards and social posts from these (COMP-001).

<ul class="pb-cards">
${contracts.map((c) => `  <li><a href="${c.slug}.html"><strong>${c.name}</strong></a><br><span class="gg-type-small">${c.summary}</span></li>`).join('\n')}
</ul>
`));

// ---- tokens ----------------------------------------------------------------------------------
const tokens = JSON.parse(readFileSync('tokens/build/tokens.json', 'utf8')).tokens;
const at = (p) => tokens[p].value;
const families = [...new Set(Object.keys(tokens).filter((p) => p.startsWith('color.')).map((p) => p.split('.')[1]))];
const swatches = families.map((f) => `<h3>${f}</h3>\n<ul class="pb-swatches">\n${Object.keys(tokens).filter((p) => p.startsWith(`color.${f}.`)).map((p) => {
  const name = p.slice(6).replace('.', '-');
  return `  <li><div class="pb-swatch__chip" style="background: var(--gg-color-${name})"></div><span class="gg-type-small">${name} <code>${at(p)}</code></span></li>`;
}).join('\n')}\n</ul>`).join('\n\n');
const pairs = ['| Text or action | On | Contrast | Needs |', '|---|---|---|---|',
  ...ROLE_PAIRS.map(([fg, bg, min]) => `| \`${fg.slice(5)}\` | \`${bg.slice(5)}\` | ${contrastRatio(at(fg), at(bg)).toFixed(2)}:1 | ${min}:1 |`)].join('\n');
const roles = ['display', 'h1', 'lead', 'h2', 'h3', 'h4', 'body', 'small', 'caption'];
const type = ['| Role | Narrow, under 768px | Wide, 768px and up | Weight | Class |', '|---|---|---|---|---|',
  ...roles.map((r) => `| <span class="gg-type-${r}">${r}</span> | ${at(`type.${r}.narrow.size`)}/${at(`type.${r}.narrow.line`)} | ${at(`type.${r}.wide.size`)}/${at(`type.${r}.wide.line`)} | ${at(`type.${r}.weight`)} | \`gg-type-${r}\` |`)].join('\n');
const space = ['| Step | Value | Custom property |', '|---|---|---|',
  ...Object.keys(tokens).filter((p) => p.startsWith('space.')).map((p) => `| ${p.slice(6)} | ${at(p)} | \`--gg-${p.replace(/\./g, '-')}\` |`)].join('\n');
mkdirSync('playbook', { recursive: true });
writeFileSync('playbook/tokens.md', page({ title: 'Tokens' }, `
# Tokens

The values in \`tokens/*.json\`, as the theme uses them. Values are changed in Figma and sent back by pull request (D-029). Every color is a custom property, \`--gg-color-…\` and \`--gg-role-…\`.

## Color

${swatches}

## Color roles and contrast

D-030. Text needs 4.5:1 on its surface; an action needs 3:1 against the surface around it.

${pairs}

## Type

Alegreya Sans only (D-020). Sizes in px, size/line height (D-026, D-027).

${type}

## Space

${space}
`));

// ---- formats ---------------------------------------------------------------------------------
const byName = Object.fromEntries(contracts.map((c) => [c.slug, c]));
const printEvent = byName['event-details'].examples.find((e) => !e.params.href).params;
const webEvent = byName['event-details'].examples.find((e) => e.params.href).params;
const ev = (p) => includeTag(byName['event-details'], p);
const FORMATS = [
  { slug: 'flyer', title: 'Flyer, Letter', layout: 'gg-flyer', size: '612×792pt', body: ['{% include gg/wordmark.html %}', '{% include gg/art-placeholder.html %}', ev(printEvent)] },
  { slug: 'postcard-front', title: 'Postcard, front', layout: 'gg-postcard', size: '306×396pt', body: ['{% include gg/art-placeholder.html %}', '{% include gg/wordmark.html %}'] },
  { slug: 'postcard-back', title: 'Postcard, back', layout: 'gg-postcard', size: '306×396pt', body: [ev(printEvent), '{% include gg/wordmark.html %}'] },
  { slug: 'postcard-sheet', title: 'Postcard, sheet of four', layout: 'gg-postcard-sheet', size: '612×792pt', body: ['{% include gg/art-placeholder.html %}', '{% include gg/wordmark.html %}'] },
  { slug: 'social-feed', title: 'Social, feed', layout: 'gg-social', extra: { size: 'feed' }, size: '1080×1350px', body: ['{% include gg/wordmark.html %}', '{% include gg/art-placeholder.html %}', ev(webEvent)] },
  { slug: 'social-story', title: 'Social, story', layout: 'gg-social', extra: { size: 'story' }, size: '1080×1920px', body: ['{% include gg/wordmark.html %}', '{% include gg/art-placeholder.html %}', ev(webEvent)] },
  { slug: 'social-cover', title: 'Social, event cover', layout: 'gg-social', extra: { size: 'cover' }, size: '1920×1005px', body: ['{% include gg/art-placeholder.html %}', `<div class="gg-social__side">\n{% include gg/wordmark.html %}\n${ev(printEvent)}\n</div>`] },
];
rmSync('playbook/formats', { recursive: true, force: true });
mkdirSync('playbook/formats', { recursive: true });
for (const f of FORMATS) {
  writeFileSync(`playbook/formats/${f.slug}.html`, page({ title: f.title, layout: f.layout, ...(f.extra || {}) }, f.body.join('\n')));
}
writeFileSync('playbook/formats/index.md', page({ title: 'Formats' }, `
# Formats

Print and social formats are pages at a fixed size, captured to PDF or PNG (D-005, D-043). They mirror the Figma templates; the art is a placeholder until the art direction is in (D-035). Content here is placeholder text (COMP-004).

| Format | Size | Layout |
|---|---|---|
${FORMATS.map((f) => `| [${f.title}](${f.slug}.html) | ${f.size} | \`${f.layout}\`${f.extra ? `, size: ${f.extra.size}` : ''} |`).join('\n')}

Print pages show 1px as 1pt (D-034): print them at 100% on Letter paper with no margins.
`));

console.log(`built the playbook pages: ${contracts.length} components, tokens, ${FORMATS.length} formats`);
